import math

def average_particle_life_span(n, m, grid):
    def bfs(start, end, grid):
        queue = [start]
        distance = {(start): 0}

        while queue:
            current = queue.pop(0)
            if current == end:
                return distance[current]
            for neighbor in [(current[0]+1, current[1]), (current[0]-1, current[1]), (current[0], current[1]+1), (current[0], current[1]-1)]:
                if 0 <= neighbor[0] < n and 0 <= neighbor[1] < m and grid[neighbor[0]][neighbor[1]] == '.' and (neighbor not in distance):
                    distance[neighbor] = distance[current] + 1
                    queue.append(neighbor)
        return -1  # Impossible path

    total_particles = 0
    global_positions = set()

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                total_particles += 1
                global_positions.add((i, j))

    for start in global_positions:
        for end in global_positions:
            if start == end:
                continue
            if start != end and end != (math.sqrt(2), math.sqrt(2)):
                distance = bfs(start, end, grid)
                if distance != -1:
                    total_particles -= 1
                    global_positions.remove((math.sqrt(2), math.sqrt(2)))

    average_life_span = math.sqrt(2) * total_particles / (n*m)
    return average_life_span

