    for i in range(len(rank_counts)):
        for j in range(i, min(len(rank_counts), i + 3)):
            if rank_counts[i] and rank_counts[j]:
                v = x * lcm(y, i)
                g = gcd(v, j)
                l = lcm(i, lcm(v // g, j))
                if g == x and l == y:
                    pairs += rank_counts[i] * rank_counts[j]

    return pairs

