from collections import deque

def bfs(grid, start):
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    visited[start[0]][start[1]] = True
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == '.':
                queue.append((nx, ny))
                visited[nx][ny] = True

    return list(queue)

def max_connected_component(grid, range_size):
    m, n = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque()
    max_area = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '.' and max(queue) < range_size:
                start = (i, j)
                queue.extend(bfs(grid, start))
                clear_space_to_end = min(range_size - max(queue), m - i) + min(range_size - max(queue), n - j)
                area = clear_space_to_end + len(queue) - 1
                if area > max_area:
                    max_area = area

    return max_area
