def max_connected_component(grid, k):
    n = len(grid)
    largest_component = set()
    for r in range(n):
        for c in range(n):
            if (r, c) not in largest_component and grid[r][c] == '.':
                if (max(1, r - k), max(1, c - k)) in largest_component and (min(n, r + k), min(n, c + k)) in largest_component:
                    # Check if the block is within Limak's range and still connected
                    block_set = set()
                    for dr in range(2 * k + 1):
                        for dc in range(2 * k + 1):
                            br = min(r + k + dr, n - 1)
                            bc = min(c + k + dc, n - 1)
                            if grid[br][bc] != 'X':
                                block_set.add((br, bc))
                    for x, y in largest_component:
                        if (x + k, y + k) not in block_set and (x, y + k) not in block_set and (x + k, y) not in block_set:
                            largest_component.add((x + k, y))
                else:
                    largest_component.clear()

    return len(largest_component)

