from collections import defaultdict

def find_max_sum_and_pairs(n, m, r, table):
    max_sum = -1
    pairs_count = 0

    for i1 in range(n - 2*r + 1):
        for j1 in range(m - 2*r + 1):
            for i2 in range(n - 2*r + 1):
                for j2 in range(m - 2*r + 1):
                    # Check for overlapping by comparing x and y ranges
                    if (i1 >= i2 + 2*r or i2 >= i1 + 2*r) or (j1 >= j2 + 2*r or j2 >= j1 + 2*r):
                        continue
                    # Calculate the sum of the corresponding cells in this combination
                    local_max = max_sum
                    for a in (i1, i1 + 1, i2 + 1): 
                        for b in (j1, j1 + 1, j2 + 1): 
                            local_max += table[a][b]
                            local_sum = local_max + find_sum(a + 1, b + 1, i2, j2, table)
                            if local_sum > max_sum:
                                max_sum = local_sum
                                pairs_count = 1
                            elif local_sum == max_sum:
                                pairs_count += 1

    return max_sum, pairs_count

def find_sum(x, y, i, j, table):
    if x == i + 1:
        return sum(table[i + 1 - x][y:y + 4])
    elif x == j + 1:
        return sum(table[y + 1 - y][i:i + 4])
    else:
        return sum(table[x - 1][y:y + 3]) + sum(lispermute_table((table[y:y + i - 1], [x], table[y + i - 1:i - 1]), i, j))

class lispermute_table:
    def __init__(self, data, row_cuts, col_cuts):
        self.n = len(data)
        self.data = data
        self.row_cuts = row_cuts
        self.col_cuts = col_cuts

    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return (self.row_cuts == other.row_cuts and
                    self.col_cuts[::-1] == other.col_cuts[::-1])
        return False

    def __ne__(self, other):
        return not self.__eq__(other)

    def __len__(self):
        return self.n

    def __iter__(self):
        return self.data[:]

    def __getitem__(self, p):
        return self.data[p-1]

    def permute(self, up_to):
        dim = (len(self.data[0]) - 1) / self.n
        if up_to % int(dim) == 3: # [3,0] [4,0] [4,1]
            if len(self.row_cuts) - 1 > up_to: return
            yield lispermute_table(self.data, self.row_cuts[0:up_to], [3, self.col_cuts[up_to]])  # [3,0] [3,1] [3,2], [0,0] [0,1] [0,2]
            yield lispermute_table([slice(i[0] - 1, i[0] + 1) for i in self.row_cuts], self.col_cuts[:up_to + 1], self.col_cuts[up_to + 1:])
        elif up_to % int(dim) == 1: # [0,3] [0,4] [0,5]
            if up_to + 1 in (self.row_cuts or []): return
            if len(self.col_cuts) - 1 > up_to: return
            yield lispermute_table([self.row_cuts[up_to]] * self.n, self.row_cuts[:up_to + 1], self.col_cuts[:up_to + 1]) # [0,3] [0,4] [0,5]
            yield lispermute_table(self.data, self.col_cuts, self.col_cuts[:up_to + 1])
        else: # [1,2]
            if up_to not in (self.row_cuts or []): return
            if len(self.col_cuts) > up_to + 1: return
            yield lispermute_table([self.row_cuts[up_to]] * self.n, [i[up_to] for i in self.row_cuts], self.col_cuts[:up_to + 1])

# Read input
