from collections import defaultdict
import numpy as np

def count_colors(matrix, colors):
    color_counts = defaultdict(int)
    for row in matrix:
        for col in range(len(row)):
            if row[col] in colors:
                color_counts[row[col]] += 1
    return color_counts

def count_squares(matrix, colors):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    squares = []
    for y in range(rows):
        for x in range(cols):
            for dy in range(0, rows - y):
                for dx in range(0, cols - x):
                    if matrix[y:y+dy+1, x:x+dx+1] == [[c] * (dx+1) for c in colors[y:y+dy+1]]:
                        squares.append((dy, dx))
    return sorted(squares)

def evaluate_squares(matrix, squares, color_counts, K):
    cost = np.zeros(K, dtype=int)
    for i, (dy, dx) in enumerate(squares):
        for y in range(1, dy+1):
            for x in range(1, dx+1):
                if matrix[y-1, x-1] in color_counts:
                    # Possible new color
                    new_color = list(color_counts)[i] if len(color_counts) == 1 else list(color_counts)[2*i]
                    for c in new_color:
                        cost[i] += c
                        cost[2*i] += c
                        cost[2*i+1] += c
                        color_counts[c] -= 1
    # Ensure each color limit is >= 0
    for c in range(K):
        if color_counts[c] < 0:
            while color_counts[c] < 0:
                i = K-color_counts[c]
                if cost[i] == float('inf') or i == 0:
                    cost[i] = float('inf')
                    break
    return color_counts, cost.sum()

def main():
    T = int(input())
    for _ in range(T):
        N, M = map(int, input().split())
        board = []
        for _ in range(N):
            row = list(input().strip())
            for i, c in enumerate(row):
                if c == '?':
                    board.append(["?"] * N)
                else:
                    board.append(c)
        K = min(N, M)
        CW, W = [], []
        CB, B = [], []
        for i in range(K):
            CW.append(int(input()))
        for i in range(K):
            CB.append(int(input()))
        square_counts = count_squares(board, [1, '?', 'white', 'black'])
        colors = [chr(ord('0') + i) for i in range(4)] + ['black', 'white', '?']
        color_counts = {color:i for i, color in enumerate(colors)}

        while square_counts:
            _, optimal_cost = evaluate_squares(board, square_counts, color_counts, K)
            # Remove squares thought to be optimal
            K -= 1
            if optimal_cost > float('inf'):
                K -= 1
            square_counts = count_squares(board, color_counts.keys()[:K])
            color_counts, next_optimal_cost = evaluate_squares(board, square_counts, color_counts, K)
            colors[max(K-3, 0):K+2] = B[max(K-3, 0):K+2] = [next_optimal_cost] * (max(K, len(B)))

        for i in range(N):
            col = 0
            for j in range(M):
                if j < i or i < j < N or j - i > M - N:
                    print(0, end='')
                    continue
                if col >= K and board[i][j] == '?':
                    print(next_optimal_cost[col - K], end='')
                    col += 1
                else:
                    print(board[i][j], end='')
            print()

if __name__ == "__main__":
