def solve(n, m, p):
    MOD = p
    dp = [[0] * (2 * m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][1] = 1
        for j in range(m + 1):
            dp[i][j + 1] = (dp[i][j + 1] + modpow(((j + 1) % (2 * m) + 1) // 2, i, MOD)) % MOD
            mod = modpow(i, i + 1, MOD)
            for k in range(m + 1, 0, -1):
                dp[i][j + k] = ((dp[i][j + k] + ((j + k - 1) % (2 * m) + 1) // 2 * dp[j][k - 1]) % MOD) * mod % MOD

    result = 0
    for i in range(1, n + 1):
        result = (result + (i - 1) * dp[i][m]) % MOD

    return result

def modpow(x, y, m):
    if y == 0:
        return 1
    elif y % 2 == 0:
        return modpow((x * x) % m, y // 2, m) % m
    else:
        return (x * modpow((x * x) % m, (y - 1) // 2, m) % m) % m

