def calculate_average_life_span(n, m, maze, persistent):
    def neighbours(cell, maze):
        x, y = cell
        directions = {(-1, 0), (1, 0), (0, -1), (0, 1)}
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                yield (nx, ny)

    static_neighbours = defaultdict(set)
    for x, row in enumerate(maze):
        for y, cell in enumerate(row):
            if cell == 'X':
                static_neighbours[(x, y)].update(neighbours((x, y), maze))
            elif cell == '.':
                static_neighbours[(x, y + 1)].update(neighbours((x, y + 1), maze))
                static_neighbours[(x, y - 1)].update(neighbours((x, y - 1), maze))
                static_neighbours[(x + 1, y)].update(neighbours((x + 1, y), maze))
                static_neighbours[(x - 1, y)].update(neighbours((x - 1, y), maze))
                static_neighbours[(x + 1, y + 1)].update(neighbours((x + 1, y + 1), maze))
                static_neighbours[(x - 1, y - 1)].update(neighbours((x - 1, y - 1), maze))
                static_neighbours[(x - 1, y + 1)].update(neighbours((x - 1, y + 1), maze))
                static_neighbours[(x + 1, y - 1)].update(neighbours((x + 1, y - 1), maze))

    alive_cells = {(x, y) for x in range(n) for y in range(m) if maze[x][y] != 'X'}

    count = {(x, y): 0 for x in range(n) for y in range(m) if maze[x][y] != 'X'}

    def neighbor_sum(cell):
        square_root = int(sqrt(count[cell] ** 2))
        divisor = 6 if persistent else 8
        return count[cell] * 27 * square_root ** 2 - divisor * count[cell] * count[cell]

    def update_active_cell(cell):
        x, y = cell
        neighbors = static_neighbours[cell]
        count[cell] = sum(neighbor_sum(neighb)**2 for neighb in neighbors) // 4
        alive_cells.remove(cell)
        alive_cells.update(neighbors)
        if (alive_cells - {cell}).compressed():
            alive_cells.add(cell)

    def stabilize():
        cell = next(islice(alive_cells, 0, 1), None)
        if cell is None:
            return 0
        update_active_cell(cell)
        return stabilize()

    return stabilize()

