    coords = np.argwhere(table)
    min_dist = float('inf')
    for i, j in coords:
        for ii, jj in coords:
            dist = np.linalg.norm([i-ij, j-jj])
            if dist < r and dist < min_dist:
                min_dist = dist
    return int(min_dist)

def split_table(table, r):
    coords = np.argwhere(table)
    circles = [False] * (len(coords) * 4)
    dists = [pdist([tuple(coord) for coord in coords], metric='euclidean') for _ in coords]
    for i, coord in enumerate(coords):
        for ii, jj in coords:
            dist = dists[i][ii][jj]
            circles[r*(i//20) + i%20] |= (dist < r + 1)
    for i, circle in enumerate(circles[:-1]):
        if not circle:
            circles.pop(i)
    return circles

