import heapq

def find_longest_path(n, m, marked_cells, total_cells):
    # Calculate the positions of the cells on the grid
    grid_positions = {cell: (row, col) for row in range(1, n + 1) for col in range(1, m + 1)}

    # Calculate the distances from the marked cells to each cell on the grid
    cell_distances = {tuple(cell): [0] * total_cells for cell in marked_cells}
    for cell in marked_cells:
        for position in grid_positions.values():
            dis = max(
                abs(position[0] - cell[1]), 
                abs(position[1] - cell[0])
            )
            cell_distances[tuple(cell)][position[0] + position[1] * (n + 1)] = dis

    # Initialize the answer
    answer = 0
    answer_next_cells = [(cell_distances[tuple(marked_cells[0])][0] + cell_distances[tuple(marked_cells[1])][0], [marked_cells[0], marked_cells[1]])]

    # Round-robin approach to find the longest path
    for i in range(total_cells * 2):
        current_answer, current_next_cells = answer, heapq.heappop(answer_next_cells)
        if i % 2 == 0:
            answer = max(answer, current_answer)
            answer_next_cells = [(current_answer + current_next_cells[1][1] + current_next_cells[1][0], current_next_cells[1])]
        else:
            lowest_triangle_index = current_next_cells[1][0] + i // 2
            if lowest_triangle_index < total_cells:
                new_cell = (current_answer + answer_next_cells[lowest_triangle_index][1] + current_answer, current_next_cells[1])
                new_triangle_index = lowest_triangle_index + 1 if i == 1 else lowest_triangle_index

                answer_next_cells = heapq.heapreplace(answer_next_cells, (new_triangle_index, new_cell))

    # Reconstruct the path
    path = [tuple(marked_cells[0])]
    for direction in (1, -1):
        for i in range(1, answer + 1):
            if len(path) == len(marked_cells[0]) + 2 and answer % 2 == 0:
                break
            next_cell = next(path)
            for neighbor in next_cell:
                coordinate_index = neighbor[0] + neighbor[1] * (n + 1)
                if coordinate_index >= len(answer_next_cells) or (i // 2 + 1) % 2 == 0 and coordinate_index < len(answer_next_cells):
                    continue
                next_cell = next(path)
                path += [coordinate_index]
            if answer % 2 == 0:
                path.append(tuple(marked_cells[1]))
                break
    return answer, path

