            unattractive_breakfasts.add(i)
            count += 1
        elif allowed_attract_worst < attractor:
            attractive_breakfasts.add(i)

    change_breakfasts_needed = 0
    for i in range(N - count):
        if i in unattractive_breakfasts:
            for j in range(N):
                if not (j in unattractive_breakfasts or (j in attractive_breakfasts and attractive_breakfasts[j] <= attractor) or (j in unattractive_breakfasts and not attractive_breakfasts[j])):
