import sys

def parse_input():
    n, m, k = map(int, input().split())
    return n, m, k

def build_graph(n, edges, graph):
    for u, v, y in edges:
        graph[u - 1].append((v - 1, y))
        graph[v - 1].append((u - 1, y))
    return graph

def find_solution(n, m, edges, graph):
    labels = [0] * n
    for u, v, y in edges:
        mask = 0
        for j in graph[u - 1] + graph[v - 1]:
            if labels[j[0]] & j[1] == 0:
                label = labels[j[0]] ^ j[1] ^ y
                labels[j[0]] = label
                mask |= label
        labels[u - 1] |= mask
        labels[v - 1] |= mask
    return labels

def recursive_solution(n, m, k, labels, graph):
    if k == 1:
        return labels[:]
    n_minus_1 = find_solution(n - 1, m, graph, labels)
    for j in range(len(graph[n - 1])):
        if labels[j] != 0 and (k & 1):
            k >>= 1
            labels[j] <<= 1
    return recursive_solution(n - 1, m, k, n_minus_1, graph)

def main():
    n, m, k = parse_input()
    edges = [tuple(map(int, input().split())) for _ in range(m)]
    graph = build_graph(n, edges, {})
    solution = recursive_solution(n, m, k, labels=[], graph=graph)
    if solution is not None:
        print(' '.join(map(str, solution)))
    else:
        print(-1)

if __name__ == "__main__":
    main()
