import sys

def flood_fill(grid, x, y, k):
    if x >= k or y >= k or x < 0 or y < 0 or grid[x][y] == 'X':
        return 0
    grid[x][y] = 'Z'  # Mark the cell as visited
    return 1 + flood_fill(grid, x+1, y, k) + flood_fill(grid, x-1, y, k) + \
           flood_fill(grid, x, y+1, k) + flood_fill(grid, x, y-1, k)

def find_max_connected_component(grid, k):
    size_map = {}
    for row in grid:
        for cell in row:
            if cell not in ['X', 'Z']:
                if k**2 in size_map:
                    size_map[k**2] = min(size_map[k**2], find_min_size(grid, row, "0") + find_min_size(grid, [""], "0") - 1)
                else:
                    size_map[k**2] = find_min_size(grid, row, "0")
    return max(size_map.values())

def find_min_size(grid, row, prefix):
    if not row:
        return prefix == ''
    min_size = prefix == '0'
    for cell in row:
        if cell not in ['X', 'Z']:
            min_size = min(min_size, find_min_size(grid, grid[row][:grid[row].index(cell)] + '', prefix + cell), 
                           find_min_size(grid, grid[row][grid[row].index(cell)+1:], '') - 1)
    return min_size

