            total_drain = 0
            for a, b in [(i, j), (i, b), (a, j)]:
                if a in new_armor and b in new_weapon:
                    total_drain += 1
            new_armor_after_comb = set()
            for a in armor - {i}:
                for ia in sorted(armor - [a] for a in new_armor):
                    for b in sorted(weapon - {j} for j in new_weapon):
                        if a <= ia and b <= j:
                            new_armor_after_comb.add(ia)
            min_hours = min(min_hours, q + 1 + len(new_armor_after_comb) + total_drain)
    return min_hours

