from collections import defaultdict
from itertools import groupby

def find_cyclical_isomorphic_substring_indices(s):
    symbols = defaultdict(set)
    for i, group in enumerate(groupby(s)):
        symbols[sum(1 for _ in group)].add(i)

    def find_candidates_for_index(index):
        if symbols[index % 26] == {0}:  # If there's only one symbol left
            candidates = symbols[index % 26 - 1] if index % 26 > 0 else symbols[index % 26 + 1]
        else:
            candidates = symbols[index % 26] - {0}
        slow, fast = index, index
        while slow + fast + 1 < 26 and events[slow + fast + 1] is not None:
            slow, fast, events[slow + fast + 1] = slow, fast + 2, events.get(slow + fast + 1, None)
        if events[slow + fast + 1] is not None:
            candidates |= set({slow, slow + 1, fast + 1})

        return frozenset(candidates)

    events = defaultdict(set)

    for i, occurrence in symbols.items():
        for c in occurrence:
            events[i + c] = occurrence

    endpoints = {}
    for i in range(26):  # 26 letters in the alphabet
        endpoints[i] = i if symbols[i] else None

    for i in range(1, 26):
        endpoints[i] = endpoints[i - 1]

    for num, candidates in endpoints.items():
        if candidates is None:
            continue

        for candidate in candidates:
            index = candidate % 26
            if index != 0:
                found = 0
                for c in range(26):
                    left, right = candidate - index + c, candidate - index - c
                    if left >= 26 or right < 0:  # Out of bounds of the string
                        continue
                    next_in = candidate + 2 * index * 12 
                    if next_in > 26 - right:
                        break

                    found = found | any(s or e == next_in   # Only check lowercase letters
                                       for s in symbols[left]
                                       for e in symbols[right])
                if found:
                    symbols[index].add(candidates)

    ans = [0] * len(symbols[0]) # Symbols.answer is supposed to be a method, so we'll assume it's a list reference
    for index in range(len(symbols[0])):
        symbols[index] = sorted(symbols[index])

    return ans



