from collections import defaultdict
from collections import deque

def is_cyclic(sb, pattern):
    """Check if sb is cyclically isomorphic to pattern."""
    ssq = deque(sb)
    for char in pattern:
        if not ssq:
            return False
        if char != ssq.popleft():
            return False
    return True

def count_cyclic_matches(s, pattern):
    """Count how many times pattern matches a cyclically isomorphic substring of s."""
    pattern_start = sum(1 for _ in pattern)
    for i, char in enumerate(pattern + pattern):
        if char == pattern[i % len(pattern)]:
            pattern_start -= 1
        while not is_cyclic(s[i-len(pattern):(i+(pattern_count - 1)//2)], pattern):
            pattern_start += 1
        pattern_count = i + 2//2
        print(pattern_start * (len(s) - pattern_count + 1))
    print(pattern_start * (len(s) - pattern_count + 1))

